import java.util.*;

class Solution {
    public int[] smallestSufficientTeam(String[] req_skills, List<List<String>> people) {
            int n = req_skills.length;
                    int m = people.size();
                            
                                    // Map each skill name to a unique bit index [0, n - 1]
                                            Map<String, Integer> skillMap = new HashMap<>();
                                                    for (int i = 0; i < n; i++) {
                                                                skillMap.put(req_skills[i], i);
                                                                        }
                                                                                
                                                                                        // Convert each person's skills into a bitmask
                                                                                                int[] personSkillMask = new int[m];
                                                                                                        for (int i = 0; i < m; i++) {
                                                                                                                    int mask = 0;
                                                                                                                                for (String skill : people.get(i)) {
                                                                                                                                                Integer idx = skillMap.get(skill);
                                                                                                                                                                if (idx != null) {
                                                                                                                                                                                    mask |= (1 << idx);
                                                                                                                                                                                                    }
                                                                                                                                                                                                                }
                                                                                                                                                                                                                            personSkillMask[i] = mask;
                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                    int totalStates = 1 << n;
                                                                                                                                                                                                                                                            // dp[mask] stores the team of people (as a bitmask of person indices) 
                                                                                                                                                                                                                                                                    // that covers the skill mask with the minimum team size.
                                                                                                                                                                                                                                                                            // Initialize with -1 to indicate unreachable states.
                                                                                                                                                                                                                                                                                    long[] dp = new long[totalStates];
                                                                                                                                                                                                                                                                                            Arrays.fill(dp, -1L);
                                                                                                                                                                                                                                                                                                    dp[0] = 0L; // 0 skills covered requires 0 people
                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                    for (int i = 0; i < m; i++) {
                                                                                                                                                                                                                                                                                                                                int pMask = personSkillMask[i];
                                                                                                                                                                                                                                                                                                                                            if (pMask == 0) continue; // Skip people with no relevant skills
                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                    for (int mask = 0; mask < totalStates; mask++) {
                                                                                                                                                                                                                                                                                                                                                                                    if (dp[mask] == -1L) continue;
                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                    int nextMask = mask | pMask;
                                                                                                                                                                                                                                                                                                                                                                                                                                    long nextTeam = dp[mask] | (1L << i);
                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // If nextMask is unvisited, or this team uses fewer people
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (dp[nextMask] == -1L || Long.bitCount(nextTeam) < Long.bitCount(dp[nextMask])) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        dp[nextMask] = nextTeam;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Extract indices from the team covering all skills
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    long bestTeam = dp[totalStates - 1];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int teamSize = Long.bitCount(bestTeam);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int[] result = new int[teamSize];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int idx = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for (int i = 0; i < m; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if ((bestTeam & (1L << i)) != 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        result[idx++] = i;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return result;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }